{
var check, ex_range;
  gas_dir = point_direction(global.hip_hole_x[global.cur_bkg_index] + background_x[0], global.hip_hole_y[global.cur_bkg_index] + background_y[0],
                            global.target_x, global.target_y);
  gas_speed = point_distance(global.hip_hole_x[global.cur_bkg_index] + background_x[0], global.hip_hole_y[global.cur_bkg_index] + background_y[0],
                             global.target_x, global.target_y) * global.gas_speed_scale * global.img_scale;
                             
  if( reverse_shot ){
      gas_dir = (gas_dir + 180) mod 360;
  }

  ex_range = 0;
  check = false;

  // 発射キー押下フラグがtrueかどうかチェック
  // 押下したタイミングでfarting_timeを更新するようにする
  for(i=0; i<GAS_PATTERN_MAX; i+=1){
    if( emit_particle[i] ){
      check = true;
      // global.current_pattern = i; // Step Eventで実行
      break;
    }
  }
  ds_stack_clear(stack_gas);
  ds_stack_clear(stack_gas_num);

  switch( global.current_mode ){
  case 0: // SHOT
    if( global.current_pattern == 0 ){ // ガス欠ショボ
      part_type_direction(pt_weak_shot, gas_dir-30, gas_dir+30, 0, 0);
      part_type_speed(pt_weak_shot, gas_speed/160, gas_speed/100, -0.2, 0);
      ds_stack_push(stack_gas, pt_weak_shot);
      ds_stack_push(stack_gas_num, 1);
      gas_name = "WEAK SHOT";
      ex_range = 30;
      if( check )  global.farting_time = 1;
    /*
      part_type_direction(pt_simple, gas_dir-180, gas_dir+180, 0, 0);
     part_type_speed(pt_simple, gas_speed/300, gas_speed/200, -0.2, 0);
      ds_stack_push(stack_gas, pt_simple);
      ds_stack_push(stack_gas_num, 1);
      gas_name = "SIMPLE SHOT";
//      ex_range = 30;
      if( check )  global.farting_time = 1;
*/
    }else if( global.current_pattern == 1 ){ // 単発弱
      part_type_direction(pt_machinegun, gas_dir-5, gas_dir+5, 0, 0);
