      ds_stack_push(stack_gas, pt_weak_shot);
      ds_stack_push(stack_gas, pt_weak_burst);
      ds_stack_push(stack_gas_num, 2);
      ds_stack_push(stack_gas_num, 2);
      gas_name = "MULTI SHOT";
      ex_range = 50;
      if( check )  global.farting_time = 5;

    }else if( global.current_pattern == 3 ){ // 一度で複数発
      part_type_direction(pt_weak_mist, gas_dir-30, gas_dir+30, 0, 0);
