    }else if( global.current_pattern == 9 ){ // 濃いミストレベル広範囲
      ex_range = 110;
      part_type_direction(pt_mist, gas_dir-ex_range, gas_dir+ex_range, 0, 0);
      part_type_speed(pt_mist, gas_speed/180, gas_speed/100, -0.2, 0);
      ds_stack_push(stack_gas, pt_mist);
      ds_stack_push(stack_gas_num, 1);
      gas_name = "ULTIMATE HIP BOMB";
      if( check )  global.farting_time = 45;

    }
    break;

  case 4: // EXPERIMENT
    if( global.current_pattern == 0 ){
      part_type_direction(pt_gaslack, gas_dir-15, gas_dir+15, 0, 0);
      part_type_speed(pt_gaslack, gas_speed/240, gas_speed/100, -0.2, 0);
      ds_stack_push(stack_gas, pt_gaslack);
      ds_stack_push(stack_gas_num, 1);
      ex_range = 15;
      if( check )  global.farting_time = 1;
      gas_name = "NO MORE GAS?";

    }else if( global.current_pattern == 1 ){
      part_type_direction(pt_gaslack, gas_dir-165, gas_dir+165, 0, 0);
      part_type_speed(pt_gaslack, gas_speed/240, gas_speed/100, -0.2, 0);
      ds_stack_push(stack_gas, pt_gaslack);
      ds_stack_push(stack_gas_num, 2);
      ex_range = 165;
      if( check )  global.farting_time = 2;
      gas_name = "NO POWER?";

    }else if( global.current_pattern == 2 ){
      part_type_direction(pt_ryfle, gas_dir-5, gas_dir+5, 0, 0);
      part_type_speed(pt_ryfle, gas_speed/140, gas_speed/60, -0.2, 0);
      ds_stack_push(stack_gas, pt_ryfle);
      ds_stack_push(stack_gas_num, 1);
      ex_range = 5;
      if( check )  global.farting_time = 85;
      gas_name = "SNIPER FART";

    }else if( global.current_pattern == 3 ){
      part_type_direction(pt_weak_shot, gas_dir-30, gas_dir+30, 0, 0);
      part_type_speed(pt_weak_shot, gas_speed/180, gas_speed/80, -0.2, 0);
      ds_stack_push(stack_gas, pt_weak_shot);
      ds_stack_push(stack_gas_num, 1);
      ex_range = 60;
      if( check )  global.farting_time = ETERNAL;
      gas_name = "INFINITY FART";

    }else if( global.current_pattern == 4 ){
      part_type_direction(pt_weak_mist, gas_dir-5, gas_dir+5, 0, 0);
      part_type_speed(pt_weak_mist, gas_speed/160, gas_speed/90, -0.2, 0);
      ds_stack_push(stack_gas, pt_weak_mist);
      ds_stack_push(stack_gas_num, 0.2);
      ex_range = 5;
      if( check )  global.farting_time = 120;
      gas_name = "SUKASHI";

    }else if( global.current_pattern == 5 ){
      part_type_direction(pt_weak_shot, gas_dir-60, gas_dir+60, 0, 0);
      part_type_direction(pt_ryfle, gas_dir-60, gas_dir+60, 0, 0);
      part_type_speed(pt_weak_shot, gas_speed/220, gas_speed/100, -0.2, 0);
      part_type_speed(pt_ryfle, gas_speed/150, gas_speed/80, -0.2, 0);
      ds_stack_push(stack_gas, pt_weak_shot);
      ds_stack_push(stack_gas, pt_ryfle);
      ds_stack_push(stack_gas_num, 0.5);
      ds_stack_push(stack_gas_num, 0.5);
      ex_range = 60;
      if( check )  global.farting_time = 80;
      gas_name = "GIANT BACKFIRE";

    }else if( global.current_pattern == 6 ){
      part_type_direction(pt_ryfle, gas_dir-5, gas_dir+5, 0, 0);
      part_type_speed(pt_ryfle, gas_speed/100, gas_speed/60, -0.2, 0);
      ds_stack_push(stack_gas, pt_ryfle);
      ds_stack_push(stack_gas_num, 0.3);
      ex_range = 5;
      if( check )  global.farting_time = 120;
      gas_name = "STREAMING GAS";

    }else if( global.current_pattern == 7 ){
      ex_range = 45;
      part_type_direction(pt_weak_shot, gas_dir-ex_range*0.5, gas_dir+ex_range*0.5, 0, 0);
      part_type_direction(pt_weak_mist, gas_dir-ex_range, gas_dir+ex_range, 0, 0);
      part_type_speed(pt_weak_shot, gas_speed/150, gas_speed/100, -0.1, 0);
      part_type_speed(pt_weak_mist, gas_speed/220, gas_speed/100, -0.1, 0);
      ds_stack_push(stack_gas, pt_weak_shot);
      ds_stack_push(stack_gas, pt_weak_mist);
      ds_stack_push(stack_gas_num, 1);
      ds_stack_push(stack_gas_num, 1);
      gas_name = "GOD BREATHE";
      if( check )  global.farting_time = 45;

    }else if( global.current_pattern == 8 ){
      ex_range = 45;
      part_type_direction(pt_fire, gas_dir-ex_range, gas_dir+ex_range, 0, 0);
      part_type_speed(pt_fire, gas_speed/160, gas_speed/100, -0.02, 0);
      ds_stack_push(stack_gas, pt_fire);
      ds_stack_push(stack_gas_num, 2.5);
      if( check )  global.farting_time = 200;
      gas_name = "BIG HIP FIRE";

    }else if( global.current_pattern == 9 ){
      ex_range = 25;
      part_type_direction(pt_fire, gas_dir-ex_range, gas_dir+ex_range, 0, 0);
      part_type_speed(pt_fire, gas_speed/130, gas_speed/70, -0.02, 0);
      ds_stack_push(stack_gas, pt_fire);
      ds_stack_push(stack_gas_num, 2.8);
      if( check )  global.farting_time = 200;
      gas_name = "BIG HIP FRAME";

    }
    break;


  default:
    pt_gas_id = 0;
  }

  // 放屁量補正
  if( check ) global.farting_time *= global.gas_amount_scale;

  var gas_dir_ex, gas_speed_ex;
  // farting_time が0より大きければエフェクト発生
    if( global.farting_time  > 0 ){
    while( ! ds_stack_empty(stack_gas) ){
      pt_gas_id = ds_stack_pop(stack_gas);
      part_type_size( pt_gas_id, 0.25, 0.25,
                      ds_list_find_value(list_pt_sizeincr,
                                         ds_map_find_value(map_ptind_to_listind, pt_gas_id))* global.gas_size_scale, 0);
      // shot_num = ceil(ds_stack_pop(stack_gas_num) * global.gas_num_scale);
      
      // 発射数の設定値を反映
      shot_num = ds_stack_pop(stack_gas_num) * global.gas_num_scale;

      // synchro_modeオンなら、サウンドの音量に従って発射数を補正
      if( global.synchro_mode )
          shot_num *= get_sound_level();
      // (試験的に実装） 一つ一つ色を変えてみる → そのパーティクルすべての色が変わっちゃうのでダメ
      // set_pt_color(pt_gas_id);

      if( shot_num < 1 ){ // １未満なら，数フレームに1回発動、とする
        shot_num = -1*ceil(1.0/shot_num);
      }else{
        shot_num = ceil(shot_num);
      }
      
      // 発射！！
      part_emitter_burst(ps,hip_em,pt_gas_id,shot_num);

      // 穴が複数ある場合の処理
      for(i=0; i<global.ex_hole_num; i+=1){
        gas_dir_ex = point_direction(global.ex_hole_x[i] + background_x[0], global.ex_hole_y[i] + background_y[0], global.target_x, global.target_y);
        if( reverse_shot ){
            gas_dir_ex = (gas_dir_ex + 180) mod 360;
        }

        gas_speed_ex = point_distance(global.ex_hole_x[i] + background_x[0], global.ex_hole_y[i] + background_y[0], global.target_x, global.target_y) * global.gas_speed_scale * global.img_scale;
        if( ex_range != 0 ) part_type_direction(pt_gas_id, gas_dir_ex-ex_range, gas_dir_ex+ex_range, 0, 0);
        part_emitter_burst(ps, hip_em_ex[i], pt_gas_id, shot_num);
      }
    }

    // 発射キー押下フラグをリセット
    for(i=0; i<GAS_PATTERN_MAX; i+=1){ emit_particle[i] = false; }

    // デバッグメッセージにガス名を入れてみる
    obj_debug_window.debug_message = gas_name;
  }
}
